import argparse
from datetime import datetime, timezone
from gzip import decompress
from hashlib import sha256
from io import StringIO
import json
from pathlib import Path
from zoneinfo import ZoneInfo

import numpy as np
import pandas as pd
from pandas.tseries.holiday import (
    AbstractHolidayCalendar, GoodFriday, Holiday, USLaborDay, USMartinLutherKingJr,
    USMemorialDay, USPresidentsDay, USThanksgivingDay, nearest_workday, sunday_to_monday,
)
import yaml


SESSIONS_PER_YEAR = 252
BILL_MATURITY_DAYS = 91
PRICE_ADJUSTMENT = (
    "Yahoo split-adjusted Close (auto_adjust=False); distributions recognized on ex-date, "
    "long distributions held outside spendable cash"
)


class NYSEHolidays(AbstractHolidayCalendar):
    rules = [
        Holiday("New Year's Day", month=1, day=1, observance=sunday_to_monday),
        USMartinLutherKingJr, USPresidentsDay, GoodFriday, USMemorialDay,
        Holiday("Juneteenth", month=6, day=19, start_date="2022-01-01", observance=nearest_workday),
        Holiday("Independence Day", month=7, day=4, observance=nearest_workday),
        USLaborDay, USThanksgivingDay,
        Holiday("Christmas Day", month=12, day=25, observance=nearest_workday),
    ]


def expected_equity_sessions(start, end):
    # Include modern unscheduled full-day closures as well as recurring holidays.
    closures = pd.DatetimeIndex([
        "2001-09-11", "2001-09-12", "2001-09-13", "2001-09-14",
        "2004-06-11",  # Reagan national day of mourning
        "2007-01-02",  # Ford national day of mourning
        "2012-10-29", "2012-10-30",  # Hurricane Sandy
        "2018-12-05", "2025-01-09",  # Bush and Carter national days of mourning
    ])
    # The fixed ETF universe starts after 1998. Keep the calendar within the modern rules.
    if start < pd.Timestamp("1998-01-01"):
        raise ValueError("Equity calendar covers dates from 1998 onward")
    holidays = NYSEHolidays().holidays(start, end)
    return pd.bdate_range(start, end, inclusive="left").difference(holidays.union(closures))


def load_config(config_path="config.yaml"):
    with open(config_path, encoding="utf-8") as file:
        config = yaml.safe_load(file)
    if min(config["ols_window"], config["zscore_window"]) < 2:
        raise ValueError("OLS and z-score windows require at least two sessions")
    if not 0 <= config["exit_z"] < config["entry_z"] < config["stop_z"]:
        raise ValueError("Require 0 <= exit_z < entry_z < stop_z")
    if not config["sector_tickers"] or not 0 <= config["gross_exposure"] <= 1:
        raise ValueError("Require sector tickers and a gross exposure target between zero and one")
    config.setdefault("slippage_bps", 2.0)
    config.setdefault("cash_buffer_pct", 0.05)
    config.setdefault("financing_lag_sessions", 2)
    if not 0 < config["cash_buffer_pct"] < 1:
        raise ValueError("Require a cash buffer fraction strictly between zero and one")
    lag = config["financing_lag_sessions"]
    if not isinstance(lag, int) or lag < 2:
        raise ValueError("Require at least two equity sessions of lag for financing quotes")
    if not all(np.isfinite(config[key]) and config[key] >= 0
               for key in ("costs_bps", "slippage_bps", "short_borrow_bps")):
        raise ValueError("Costs, slippage and borrow fees must be finite and nonnegative")
    if not np.isfinite(config["short_collateral_ratio"]) or config["short_collateral_ratio"] < 1:
        raise ValueError("Collateral must cover at least 100% of shorts")
    return config



TIMESTAMP_PREFIX = "# DATA_FETCHED_AT: "


def cash_returns_from_irx(irx, index, lag):
    discount = irx.ffill(limit=5).shift(lag) / 100.0
    bill_price = 1.0 - discount * BILL_MATURITY_DAYS / 360.0
    observed = bill_price.iloc[lag:]
    if not np.isfinite(observed).all() or (observed <= 0).any():
        raise ValueError(f"Missing or invalid lagged financing quotes")
    days = index.to_series().diff().dt.days
    return np.expm1(-np.log1p(bill_price - 1.0) * days / BILL_MATURITY_DAYS)


def validate_snapshot_frames(close, distributions, irx, config):
    sectors = config["sector_tickers"]
    etfs = sectors + [config["market_ticker"], config["cash_ticker"]]
    rate_ticker = config["financing_ticker"]
    start, end = (pd.Timestamp(config[key]) for key in ("start_date", "end_date"))
    if close is None or close.empty:
        raise ValueError("Snapshot contains no usable daily ETF data")
    index = close.index
    if not isinstance(index, pd.DatetimeIndex) or index.hasnans or not index.is_unique or not index.is_monotonic_increasing:
        raise ValueError("Snapshot has an invalid daily date index")
    expected = expected_equity_sessions(start, end)
    missing, extra = expected.difference(index), index.difference(expected)
    if expected.empty or len(missing) or len(extra):
        raise ValueError(f"NYSE equity sessions mismatch: missing {list(missing[:5].date)}, extra {list(extra[:5].date)}")
    missing_cols = [c for c in etfs if c not in close.columns or c not in distributions.columns]
    if missing_cols:
        raise ValueError(f"Snapshot is missing ETF columns: {missing_cols}")
    if irx.name != rate_ticker and rate_ticker not in getattr(irx, 'index', []):
        # irx is a Series named after the ticker
        if getattr(irx, 'name', None) != rate_ticker:
            raise ValueError(f"Snapshot is missing financing quote {rate_ticker}")
    listing_dates = config["sector_listing_dates"]
    for ticker in etfs:
        listed = index >= pd.Timestamp(listing_dates.get(ticker, config["start_date"]))
        if close.loc[~listed, ticker].notna().any() or distributions.loc[~listed, ticker].notna().any():
            raise ValueError(f"{ticker} has a quote before its configured listing date")
        observed = close.loc[listed, ticker]
        dist = distributions.loc[listed, ticker]
        if not np.isfinite(observed).all() or (observed <= 0).any():
            raise ValueError(f"Incomplete or invalid Close for listed ETF {ticker}")
        if not np.isfinite(dist).all():
            raise ValueError(f"Incomplete or invalid Distributions for listed ETF {ticker}")
    if not irx.index.equals(index):
        raise ValueError("Financing quote index does not match equity sessions")


def load_market_data(config, config_path="config.yaml"):
    today_ny = datetime.now(ZoneInfo("America/New_York")).date()
    start, end = (pd.Timestamp(config[key]).date() for key in ("start_date", "end_date"))
    if not start < end <= today_ny:
        raise ValueError("Use a nonempty date range whose exclusive end is no later than today in New York")

    data = config.get("data") or {}
    blob = data.get("market_snapshot_gzip")
    expected_digest = data.get("market_snapshot_sha256")
    if not isinstance(blob, (bytes, bytearray)) or not expected_digest:
        raise ValueError("config.data must carry market_snapshot_gzip and market_snapshot_sha256")
    snapshot = decompress(bytes(blob))
    digest = sha256(snapshot).hexdigest()
    if digest != expected_digest:
        raise ValueError(
            f"SHA-256 mismatch for the Yahoo Finance snapshot in {Path(config_path).name}: {digest}."
        )
    text = snapshot.decode("utf-8")
    header, sep, body = text.partition("\n")
    if not header.startswith(TIMESTAMP_PREFIX) or not sep:
        raise ValueError("Missing cache timestamp")
    fetched_at = header.removeprefix(TIMESTAMP_PREFIX).strip()
    if datetime.fromisoformat(fetched_at).utcoffset() is None:
        raise ValueError("Cache timestamp must have a time zone")
    input_digest = sha256(body.encode("utf-8")).hexdigest()
    fields = pd.read_csv(StringIO(body), header=[0, 1], index_col=0, parse_dates=True)
    close = fields["Close"]
    distributions = fields["Distributions"]
    irx = fields["Financing quote"][config["financing_ticker"]]
    validate_snapshot_frames(close, distributions, irx, config)
    cash_returns = cash_returns_from_irx(irx, close.index, config["financing_lag_sessions"])
    provenance = {
        "path": Path(config_path).name,
        "key": "data.market_snapshot_gzip",
        "sha256": digest,
    }
    print(
        "Data source: Yahoo Finance snapshot embedded in config under data.market_snapshot_gzip "
        f"(decompressed sha256 {digest}); daily Close and cash distributions. "
        "The script does not call yfinance or read data_cache."
    )
    print(f"DATA_FETCHED_AT: {fetched_at}")
    print(f"PRICE_ADJUSTMENT: {PRICE_ADJUSTMENT}")
    print(f"Input SHA-256: {input_digest}")
    print(f"DATA_SHA256: {digest}")
    print(f"MARKET_DATA_SNAPSHOT: {json.dumps(provenance, allow_nan=False)}")
    print(f"Price sessions: {len(close)} ({close.index[0].date()} to {close.index[-1].date()})")
    return close, distributions, cash_returns


def build_signals(total_returns, config):
    sectors = config["sector_tickers"]
    market = total_returns[config["market_ticker"]]
    sector_returns = total_returns[sectors]
    ols_window = config["ols_window"]
    z_window = config["zscore_window"]

    # Roll each sector on a complete paired window ending the session before the signal.
    residuals = {}
    for ticker in sectors:
        sector = sector_returns[ticker]
        paired_market = market.where(sector.notna())
        market_window = paired_market.rolling(ols_window)
        variance = market_window.var(ddof=0).where(lambda value: value > 1e-12)
        beta = sector.rolling(ols_window).cov(paired_market, ddof=0) / variance
        alpha = sector.rolling(ols_window).mean() - beta * market_window.mean()
        residuals[ticker] = sector - alpha.shift(1) - beta.shift(1) * market

    cumulative = pd.DataFrame(residuals).cumsum()
    recent = cumulative.rolling(z_window)
    scores = (cumulative - recent.mean()) / recent.std().where(lambda value: value > 0)

    entry, exit_, stop = (config[key] for key in ("entry_z", "exit_z", "stop_z"))
    side_weight = config["gross_exposure"] / 2.0
    state = np.zeros(len(sectors))
    targets = []
    for score in scores.to_numpy():
        flat = state == 0
        long_entry = flat & (score > -stop) & (score < -entry)
        short_entry = flat & (score > entry) & (score < stop)
        long_exit = (state > 0) & ((score >= -exit_) | (score <= -stop))
        short_exit = (state < 0) & ((score <= exit_) | (score >= stop))
        state[long_exit | short_exit | ~np.isfinite(score)] = 0
        state[long_entry] = 1
        state[short_entry] = -1

        target = np.zeros_like(state)
        for side in (1, -1):
            active = state == side
            if active.any():
                target[active] = side * side_weight / active.sum()
        targets.append(target)
    weights = pd.DataFrame(targets, index=scores.index, columns=sectors)
    return weights, scores.notna().any(axis=1)


def cash_after_trade(positions, share_changes, marks, cash, cost_rate, collateral_ratio):
    trade_values = share_changes * marks
    notional = np.abs(trade_values).sum()
    short_value = -np.minimum(positions * marks, 0).sum()
    return cash - trade_values.sum() - cost_rate * notional, collateral_ratio * short_value, notional


def size_next_close_order(weights, prior_marks, equity, shares, cash, cost_rate, collateral_ratio, buffer_pct):
    """Set next-session positions using only the sizing close and its settled balances."""
    # A zero target before listing needs no quote. Remove numerical dust at the sizing close.
    active_marks = prior_marks[(weights != 0) | (shares != 0)]
    if not np.isfinite(active_marks).all() or (active_marks <= 0).any():
        raise ValueError("Missing or invalid prior closing price for sizing")
    target = np.divide(equity * weights, prior_marks, where=weights != 0, out=np.zeros_like(weights, dtype=float))
    tiny = (weights != 0) & (np.abs((target - shares) * prior_marks) <= equity * 1e-12)
    target[tiny] = shares[tiny]
    reserve = equity * buffer_pct

    projected_cash, projected_collateral, _ = cash_after_trade(
        target, target - shares, prior_marks, cash, cost_rate, collateral_ratio,
    )
    if projected_cash - projected_collateral >= reserve:
        return target

    reduced = np.zeros_like(target)
    projected_cash, projected_collateral, _ = cash_after_trade(
        reduced, reduced - shares, prior_marks, cash, cost_rate, collateral_ratio,
    )
    if projected_cash - projected_collateral < reserve:
        raise RuntimeError("Insufficient equity to close positions and fund the required cash reserve")

    # Free cash is concave in the target scale because fees depend on absolute share changes.
    lower, upper = 0.0, 1.0
    for _ in range(48):
        scale = (lower + upper) / 2.0
        candidate = target * scale
        projected_cash, projected_collateral, _ = cash_after_trade(
            candidate, candidate - shares, prior_marks, cash, cost_rate, collateral_ratio,
        )
        if projected_cash - projected_collateral >= reserve:
            lower, reduced = scale, candidate
        else:
            upper = scale
    return reduced


def run_backtest(prices, distributions, cash_returns, weights, start_row, config, *, rebalance=True):
    """Simulate equity and cash per $1 of starting capital."""
    if start_row >= len(prices):
        return pd.DataFrame(index=prices.index[start_row:])
    if start_row < 1:
        raise ValueError("The first fill requires a prior closing session for sizing")
    if not np.isfinite(cash_returns.iloc[start_row:]).all():
        raise ValueError("Missing or invalid financing return during the evaluation period")
    fee_rate = config["costs_bps"] / 10_000.0
    slippage_rate = config["slippage_bps"] / 10_000.0
    cost_rate = fee_rate + slippage_rate
    borrow_rate = config["short_borrow_bps"] / 10_000.0
    collateral_ratio = config["short_collateral_ratio"]
    buffer_pct = config["cash_buffer_pct"]
    marks = prices[weights.columns].fillna(0).to_numpy()
    payouts = distributions[weights.columns].fillna(0).to_numpy()
    cash_rates = cash_returns.to_numpy()
    targets = weights.to_numpy()
    days = prices.index.to_series().diff().dt.days.to_numpy()

    cash = equity = 1.0
    collateral = short_value = reserved_distributions = 0.0
    shares = np.zeros(marks.shape[1])
    daily_results = []
    for fill_row in range(start_row, len(prices)):
        # Lock the share changes and trade count before reading the fill session's inputs.
        next_shares = shares
        if rebalance or fill_row == start_row:
            sizing_row = fill_row - 1
            next_shares = size_next_close_order(
                targets[sizing_row], marks[sizing_row], equity, shares, cash,
                cost_rate, collateral_ratio, buffer_pct,
            )
        share_changes = next_shares - shares
        n_trades = int(np.count_nonzero(share_changes))

        # Mark the old positions and accrue their cash flows before settling the fixed shares.
        fill_date = prices.index[fill_row].date()
        mark = marks[fill_row]
        active_marks = mark[(next_shares != 0) | (shares != 0)]
        if not np.isfinite(active_marks).all() or (active_marks <= 0).any():
            raise ValueError(f"Missing or invalid closing price for settlement on {fill_date}")
        # Yahoo supplies ex-dates here. Hold long entitlements outside spendable cash
        # throughout the simulation and reserve short obligations immediately.
        long_distribution = np.maximum(shares, 0) @ payouts[fill_row]
        short_distribution = -np.minimum(shares, 0) @ payouts[fill_row]
        reserved_distributions += long_distribution
        cash_interest = (cash - collateral) * cash_rates[fill_row]
        borrow_fee = short_value * borrow_rate * days[fill_row] / 365.0
        cash += cash_interest - borrow_fee - short_distribution
        pretrade_equity = cash + shares @ mark + reserved_distributions
        if not np.isfinite(pretrade_equity) or pretrade_equity <= 0:
            raise RuntimeError(f"Nonpositive or invalid pre-trade equity on {fill_date}")

        # The fill close determines settlement values only. A shortfall aborts the simulation.
        cash, collateral, notional = cash_after_trade(
            next_shares, share_changes, mark, cash, cost_rate, collateral_ratio,
        )
        if not np.isfinite(cash - collateral) or cash < collateral:
            raise RuntimeError(
                f"Insufficient free cash to settle fixed shares on {fill_date}: "
                f"cash {cash:.8f}, required collateral {collateral:.8f} per $1 of starting capital"
            )
        short_change = (np.minimum(next_shares, 0) - np.minimum(shares, 0)) * mark
        shares = next_shares

        values = shares * mark
        long_value = np.maximum(values, 0).sum()
        short_value = -np.minimum(values, 0).sum()
        previous_equity, equity = equity, cash + long_value - short_value + reserved_distributions
        if not np.isfinite(equity) or equity <= 0:
            raise RuntimeError(f"Nonpositive or invalid post-trade equity on {fill_date}")
        gross = long_value + short_value
        daily_results.append({
            "cash": cash, "free_cash": cash - collateral, "long_value": long_value,
            "short_value": short_value, "collateral": collateral,
            "short_sale_proceeds": -np.minimum(short_change, 0).sum(),
            "short_cover_cost": np.maximum(short_change, 0).sum(),
            "gross_exposure": gross, "gross_leverage": gross / equity,
            "net_leverage": (long_value - short_value) / equity,
            "cash_interest": cash_interest, "borrow_fee": borrow_fee,
            "reserved_distributions": reserved_distributions,
            "net_distributions": long_distribution - short_distribution,
            "trading_fee": fee_rate * notional,
            "slippage_cost": slippage_rate * notional,
            "equity": equity, "return": equity / previous_equity - 1.0,
            "turnover": notional / pretrade_equity, "n_trades": n_trades,
        })
    return pd.DataFrame(daily_results, index=prices.index[start_row:])


def period_metrics(daily_results, cash_returns):
    if daily_results.empty:
        fields = ("cagr", "ann_vol", "sharpe", "sharpe_excess", "max_drawdown", "total_return", "turnover")
        return dict.fromkeys(fields) | {"n_trades": 0}

    returns = daily_results["return"]
    excess = returns - cash_returns.loc[daily_results.index]
    growth = np.r_[1.0, (1.0 + returns).cumprod()]
    vol, excess_vol = returns.std(), excess.std()
    # With repeated identical observations, floating-point rounding can leave a tiny positive std.
    if len(returns) > 1 and returns.min() == returns.max():
        vol = 0.0
    if len(excess) > 1 and excess.min() == excess.max():
        excess_vol = 0.0
    annualizer = np.sqrt(SESSIONS_PER_YEAR)
    return {
        "cagr": growth[-1] ** (SESSIONS_PER_YEAR / len(daily_results)) - 1.0,
        "ann_vol": vol * annualizer if np.isfinite(vol) else None,
        "sharpe": annualizer * returns.mean() / vol if vol > 0 else None,
        "sharpe_excess": annualizer * excess.mean() / excess_vol if excess_vol > 0 else None,
        "max_drawdown": (growth / np.maximum.accumulate(growth) - 1.0).min(),
        "total_return": growth[-1] - 1.0,
        "turnover": daily_results["turnover"].sum(),
        "n_trades": int(daily_results["n_trades"].sum()),
    }


def summarize_periods(daily_results, cash_returns, oos_start):
    return {
        "is": period_metrics(daily_results.loc[daily_results.index < oos_start], cash_returns),
        "oos": period_metrics(daily_results.loc[daily_results.index >= oos_start], cash_returns),
        "full": period_metrics(daily_results, cash_returns),
    }


def main():
    parser = argparse.ArgumentParser(description="022 Sector Residual Statistical Arbitrage Strategy")
    parser.add_argument("--smoke", action="store_true", help="Check public data and signal construction")
    parser.add_argument("--config", default="config.yaml", help="Path to config file")
    parser.add_argument("--refresh", action="store_true", help="Rejected: this run uses the embedded snapshot only")
    args = parser.parse_args()
    if args.refresh:
        raise SystemExit("This run reads the embedded Yahoo Finance snapshot only; --refresh is not supported.")

    config = load_config(args.config)
    print(f"Run directory: {Path.cwd()}")
    print(f"RUN_DIRECTORY: {Path.cwd()}")
    print(f"RUN_STARTED_AT: {datetime.now().astimezone().isoformat(timespec='milliseconds')}")
    file_sha = sha256(Path(__file__).read_bytes()).hexdigest()
    print(f"Strategy SHA-256: {file_sha}")
    print(f"STRATEGY_SHA256: {file_sha}")
    print(f"CONFIG_SHA256: {sha256(Path(args.config).read_bytes()).hexdigest()}")
    params = {key: value for key, value in config.items() if key != "data"}
    effective_config = yaml.safe_dump(params, sort_keys=True).encode("utf-8")
    print(f"Effective config SHA-256: {sha256(effective_config).hexdigest()}")
    print("PARAM_COMBOS_TRIED: 1")
    print("Historical parameter trials: unknown")
    prices, distributions, cash_rates = load_market_data(config, args.config)
    total_returns = (prices + distributions).div(prices.shift(1)) - 1.0
    weights, ready = build_signals(total_returns, config)
    ready_to_fill = np.flatnonzero(ready.to_numpy()[:-1])
    start_row = int(ready_to_fill[0] + 1) if ready_to_fill.size else len(prices)
    if args.smoke:
        print(f"Tickers: {', '.join(prices.columns)}")
        print(f"Signal dimensions: {weights.shape}; nonzero targets: {np.count_nonzero(weights)}")
        return

    daily_results = run_backtest(prices, distributions, cash_rates, weights, start_row, config)
    oos_start = pd.Timestamp(config["oos_start"])
    market = config["market_ticker"]
    cash_ticker = config["cash_ticker"]
    cash_returns = total_returns[cash_ticker]
    benchmark = run_backtest(
        prices, distributions, cash_rates, pd.DataFrame(1.0, index=prices.index, columns=[market]),
        start_row, config, rebalance=False,
    )
    print(f"Split: IS before {oos_start.date()}, retrospective OOS on or after that date; excess Sharpe vs {cash_ticker}")
    if not daily_results.empty:
        dates = daily_results.index
        ending = daily_results.iloc[-1]
        print(f"Evaluation sessions: {len(dates)} ({dates[0].date()} to {dates[-1].date()})")
        print(f"First sizing and eligible fill: {prices.index[start_row - 1].date()} close -> {dates[0].date()} close")
        print(f"Ending cash: {ending['cash']:.6f}; long value: {ending['long_value']:.6f}; "
              f"short value: {ending['short_value']:.6f}; collateral: {ending['collateral']:.6f}; "
              f"reserved long distributions: {ending['reserved_distributions']:.6f}; equity: {ending['equity']:.6f}")
        print(f"{market} reserved long distributions: {benchmark['reserved_distributions'].iloc[-1]:.6f}")
        print(f"Cash buffer at sizing: {config['cash_buffer_pct']:.2%} of prior-close equity")
        print(f"Minimum free cash per $1 starting capital: strategy {daily_results['free_cash'].min():.6f}, "
              f"{market} {benchmark['free_cash'].min():.6f}")
        gross = daily_results["gross_leverage"]
        net = daily_results["net_leverage"]
        print(f"Gross exposure/equity mean/max: {gross.mean():.4f}/{gross.max():.4f}; "
              f"net exposure/equity min/max: {net.min():.4f}/{net.max():.4f}")
        print(f"Costs, interest and distributions per $1 starting capital: "
              f"trading fees {daily_results['trading_fee'].sum():.6f}; "
              f"slippage {daily_results['slippage_cost'].sum():.6f}; "
              f"short borrow fees {daily_results['borrow_fee'].sum():.6f}; "
              f"cash interest {daily_results['cash_interest'].sum():.6f}; "
              f"net distributions {daily_results['net_distributions'].sum():.6f}")
        cash_growth = 1.0 + cash_returns.loc[dates]
        print(f"{cash_ticker} gross total return: IS {cash_growth.loc[dates < oos_start].prod() - 1.0:.6f}; "
              f"OOS {cash_growth.loc[dates >= oos_start].prod() - 1.0:.6f}; full {cash_growth.prod() - 1.0:.6f}")
    else:
        print("No session available for execution after signal warm-up")

    result = {
        "strategy": config["strategy_name"],
        "data_range": {
            "start": str(prices.index[0].date()), "end": str(prices.index[-1].date()),
            "evaluation_start": str(daily_results.index[0].date()) if not daily_results.empty else None,
            "oos_start": str(oos_start.date()),
        },
        **summarize_periods(daily_results, cash_returns, oos_start),
        "benchmark": {"ticker": market, **summarize_periods(benchmark, cash_returns, oos_start)},
    }
    print("RESULTS_JSON: " + json.dumps(result, allow_nan=False))


if __name__ == "__main__":
    main()
